CREATE CACHED TABLE IF NOT EXISTS "NEONMARKER_TAG_RULE" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SORT_ORDER" INTEGER NOT NULL,
    "TAG" VARCHAR(4096) NOT NULL,
    "COLOR" INTEGER NOT NULL,
    "ENABLED" BOOLEAN DEFAULT TRUE NOT NULL
);

CREATE CACHED TABLE IF NOT EXISTS "NEONMARKER_HISTORY_COLOR" (
    "HISTORY_ID" INTEGER PRIMARY KEY,
    "COLOR" INTEGER NOT NULL
);

CREATE CACHED TABLE IF NOT EXISTS "NEONMARKER_SETTING" (
    "SETTING_KEY" VARCHAR(256) PRIMARY KEY,
    "SETTING_VALUE" VARCHAR(4096) NOT NULL
);
